/*
 * node_modules/events — node:events-shaped EventEmitter.
 *
 * Pure JavaScript: this package is the clearest example of the node_modules
 * side of SEVM (framework/script oriented), while mochi_modules/ holds the
 * native engine plugins.
 */

export class EventEmitter {
    constructor() {
        this._handlers = Object.create(null);
    }

    on(event, fn) {
        (this._handlers[event] || (this._handlers[event] = [])).push(fn);
        return this;
    }

    once(event, fn) {
        const wrapper = (...args) => {
            this.off(event, wrapper);
            fn.apply(this, args);
        };
        return this.on(event, wrapper);
    }

    off(event, fn) {
        const list = this._handlers[event];
        if (!list) return this;
        const i = list.indexOf(fn);
        if (i >= 0) list.splice(i, 1);
        return this;
    }

    emit(event, ...args) {
        const list = this._handlers[event];
        if (!list || list.length === 0) return false;
        for (const fn of list.slice()) fn.apply(this, args);
        return true;
    }

    listenerCount(event) {
        const list = this._handlers[event];
        return list ? list.length : 0;
    }

    removeAllListeners(event) {
        if (event === undefined) this._handlers = Object.create(null);
        else delete this._handlers[event];
        return this;
    }
}

export default EventEmitter;
